// Public project identifier only. No service-role or server secrets belong here.
const CLOUD_URL='https://ezstwuzfupvsdiuzvdvv.supabase.co';
const CLOUD_KEY='sb_publishable_k8JR4vZnwCvnnXVRboSXgA_3CYgDIE6';
let identity=null,cloudAuth=JSON.parse(localStorage.getItem('stagesight-auth')||'null');
const localReport=report,localRender=render;
function authHeaders(){return {apikey:CLOUD_KEY,Authorization:'Bearer '+(cloudAuth?.access_token||CLOUD_KEY)}}
async function api(path,options={}){if(cloudAuth&&cloudAuth.expires_at*1000<Date.now()+60000){const r=await fetch(CLOUD_URL+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:CLOUD_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:cloudAuth.refresh_token})});const data=await r.json();if(!r.ok){signoutLocal();throw Error('Sign-in expired. Sign in again; keep this tab open to retry your upload.')}cloudAuth=data;localStorage.setItem('stagesight-auth',JSON.stringify(data))}const r=await fetch(CLOUD_URL+path,{...options,headers:{...authHeaders(),...options.headers}});if(!r.ok){let data;try{data=await r.json()}catch{}throw Error(data?.msg||data?.message||data?.error_description||data?.error||'Request failed ('+r.status+')')}if(r.status===204)return null;const text=await r.text();return text?JSON.parse(text):null}
function profile(){const p=$('.profile');p.innerHTML=`<div class="avatar">${identity?esc(identity.email[0].toUpperCase()):'↗'}</div><div>${identity?esc(identity.email):'Your private workspace'}<span>${identity?'Signed in · Cloud storage':'Sign in to save recordings'}</span></div><button class="text-button" id="account-action">${identity?'Sign out':'Sign in'}</button>`;$('#account-action').onclick=identity?signout:()=>authDialog();document.querySelector('.local-badge').textContent=identity?'◈ Private account':'◈ Sign in to practice';}
function authDialog(mode='signin'){modal(`<h2>${mode==='signup'?'Create your StageSight account':'Welcome to StageSight'}</h2><p>${mode==='signup'?'Save your rehearsals in your personal account.':'Sign in to record and access your private rehearsals.'}</p><form id="auth-form"><label class="field" for="auth-email">Email</label><input id="auth-email" type="email" autocomplete="email" required style="width:100%;padding:12px;border:1px solid #dce4d8;border-radius:6px"><label class="field" for="auth-password">Password</label><input id="auth-password" type="password" autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="8" required style="width:100%;padding:12px;border:1px solid #dce4d8;border-radius:6px"><p id="auth-status" role="status"></p><button class="primary" id="auth-submit" type="submit">${mode==='signup'?'Create account':'Sign in'}</button></form><p>${mode==='signup'?'Already have an account?':'New here?'} <button class="text-button" id="auth-switch">${mode==='signup'?'Sign in':'Create an account'}</button></p>`);$('#auth-switch').onclick=()=>authDialog(mode==='signup'?'signin':'signup');$('#auth-form').onsubmit=async e=>{e.preventDefault();$('#auth-submit').disabled=true;$('#auth-status').textContent='Please wait…';try{const email=$('#auth-email').value.trim(),password=$('#auth-password').value;const r=await fetch(CLOUD_URL+'/auth/v1/'+(mode==='signup'?'signup':'token?grant_type=password'),{method:'POST',headers:{apikey:CLOUD_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw Error(d.msg||d.message||d.error_description||'Unable to sign in');if(!d.access_token){$('#auth-status').textContent='Check your email to confirm your account, then return here to sign in.';return}cloudAuth=d;identity=d.user;localStorage.setItem('stagesight-auth',JSON.stringify(d));$('#dialog').close();profile();await refresh();render('home');toast('Signed in. Your recordings belong to this account.')}catch(err){$('#auth-status').textContent=err.message}finally{if($('#auth-submit'))$('#auth-submit').disabled=false}}}
function signoutLocal(){identity=null;cloudAuth=null;localStorage.removeItem('stagesight-auth');sessions=[];profile()}
async function signout(){if(recorder?.state==='recording'||pending){toast('Save or download your recording before signing out.');return}try{await api('/auth/v1/logout',{method:'POST'})}catch{}signoutLocal();stopTracks();render('home')}
refresh=async function(){if(!identity){sessions=[];return}try{const rows=await api('/rest/v1/sessions?select=*&order=created_at.desc');sessions=rows.map(s=>({...s,cloud:true,date:new Date(s.created_at).toLocaleDateString(),created:Date.parse(s.created_at)}));if(view==='home'||view==='library')render(view)}catch(e){toast('Could not load your sessions: '+e.message)}};
const oldCard=card;card=function(s,i){return oldCard(s,i).replace(s.cloud?'SAMPLE REPORT':'___',s.cloud?(s.status==='ready'?'PRIVATE CLOUD':'UPLOAD INCOMPLETE'):'___').replace(s.cloud?'◇ Explore the report':'___',s.cloud?(s.status==='ready'?'● Saved to your account':'◌ Upload incomplete'):'___')};
render=function(v){if(v==='studio'&&!identity){authDialog();return}localRender(v);if(v==='studio'&&view==='studio'){const notice=$('#save-state').nextElementSibling;notice.textContent='Private cloud storage • 50 MB per recording • Retained until you delete it';const privacyNote=$('.video-placeholder p');if(privacyNote)privacyNote.textContent='Enable your camera and microphone to get started.'}if(v==='library'&&view==='library'){const label=$('.section-head .date');if(label)label.textContent=sessions.length+' recordings in your account';const empty=$('.empty p');if(empty)empty.textContent='Sign in and save your first rehearsal to see it here.'}if(v==='home'){const p=$('.note.tint p');if(p)p.textContent='Recordings are saved in private cloud storage under your signed-in account.'}profile()};
save=async function(){if(!pending)pending={id:crypto.randomUUID(),user_id:identity?.id,title:$('#title').value.trim()||'Untitled rehearsal',type:$('#type').value,date:new Date().toLocaleDateString(),created:Date.now(),duration:seconds,transcript,blob:new Blob(chunks,{type:recorder.mimeType})};if(!pending.blob.size){toast('No video data was captured.');return}$('#save-state').innerHTML='<p>Uploading to your private account… Keep this tab open.</p>';try{if(!identity||pending.user_id!==identity.id)throw Error('Sign in to the account that started this recording.');if(pending.blob.size>52428800)throw Error('Recording exceeds the 50 MB cloud limit. Download it below; try a shorter recording.');const path=identity.id+'/'+pending.id+'/recording';const row={id:pending.id,user_id:identity.id,title:pending.title,type:pending.type,duration:pending.duration,transcript:pending.transcript||null,storage_path:path,status:'uploading',mime_type:pending.blob.type,byte_size:pending.blob.size};await api('/rest/v1/sessions?on_conflict=id',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates'},body:JSON.stringify(row)});await api('/storage/v1/object/recordings/'+path,{method:'POST',headers:{'Content-Type':pending.blob.type||'application/octet-stream','x-upsert':'true'},body:pending.blob});await api('/rest/v1/sessions?id=eq.'+pending.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'ready'})});const id=pending.id;pending=null;await refresh();await report(id);toast('Video uploaded. Session saved to your private account.')}catch(e){failed();$('#save-state .notice').textContent=e.message+' Your recording remains in this tab. Retry reuses the same session.'}};
report=async function(id){const s=sessions.find(s=>s.id===id);if(!s?.cloud){localReport(id);return}if(s.status!=='ready'){toast('This session has no confirmed completed upload. Return to its recording tab to retry.');return}try{const signed=await api('/storage/v1/object/sign/recordings/'+s.storage_path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expiresIn:300})});const url=signed.signedURL.startsWith('http')?signed.signedURL:CLOUD_URL+'/storage/v1'+signed.signedURL; // Server checks the JWT and Storage policy before signing.
const standin={...s,blob:new Blob()};sessions=sessions.map(x=>x.id===id?standin:x);localReport(id);sessions=sessions.map(x=>x.id===id?s:x);if(activeURL){URL.revokeObjectURL(activeURL);activeURL=null}$('#playback').src=url;$('#playback').onerror=()=>toast('Playback unavailable or link expired. Reopen this session to refresh.');$('#content .heading p').textContent=s.date+' · '+fmt(s.duration)+' · Private cloud recording';document.querySelectorAll('.status-line').forEach(n=>{if(n.textContent.startsWith('Video'))n.querySelector('span').textContent='Saved privately'});$('#download').onclick=async()=>{try{const r=await fetch(url);if(!r.ok)throw Error('Download link expired. Reopen this session.');download({...s,blob:await r.blob()})}catch(e){toast(e.message)}};$('#delete').onclick=()=>{modal('<h2>Delete this rehearsal?</h2><p>This permanently removes the cloud video and its session data. Downloaded copies remain on your device.</p><button class="danger" id="confirm-delete">Delete permanently</button>');$('#confirm-delete').onclick=async()=>{try{$('#confirm-delete').disabled=true;await api('/rest/v1/sessions?id=eq.'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'deleting'})});await api('/storage/v1/object/recordings',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:[s.storage_path]})});await api('/rest/v1/sessions?id=eq.'+id,{method:'DELETE'});$('#dialog').close();await refresh();render('library');toast('Cloud recording and session data deleted.')}catch(e){toast('Deletion incomplete. Retry: '+e.message);$('#confirm-delete').disabled=false}}}}catch(e){toast('Could not open private recording: '+e.message)}};
$('#privacy').onclick=()=>modal('<h2>Your private practice account</h2><p>Recordings are uploaded to a private Supabase Storage bucket. Session titles, transcripts, and recording metadata are stored in PostgreSQL. Ownership policies restrict both to your signed-in user.</p><p>The per-file limit is 50 MB. Recordings remain until you delete them; automatic cleanup is not active. Playback links expire after five minutes; reopen the session to renew.</p><p>Optional browser transcription may send audio to your browser provider. OpenAI and visual analysis are not connected. Older local prototype recordings are not automatically uploaded.</p>');
(async()=>{profile();if(cloudAuth)try{identity=await api('/auth/v1/user');profile();await refresh()}catch(e){toast(e.message);signoutLocal()}render('home')})();
const aiScript=document.createElement('script');aiScript.src='ai-client.js';document.body.appendChild(aiScript);
const sessionActionsScript=document.createElement('script');sessionActionsScript.src='session-actions.js';document.body.appendChild(sessionActionsScript);
